	"owner_id" text NOT NULL,
	"citation_id" text NOT NULL,
	"state" text NOT NULL,
	"support" text NOT NULL,
	"page_live" integer NOT NULL,
	"readable" integer NOT NULL,
	"author_known" integer NOT NULL,
	"supports_brand" integer NOT NULL,
	"created_at" text NOT NULL,
	"updated_at" text NOT NULL,
	CONSTRAINT "source_inspection_check" CHECK ("source_inspection"."state" in ('observed', 'resolved', 'limited', 'unknown')
    and "source_inspection"."support" in ('supports', 'unknown')
    and "source_inspection"."page_live" in (0, 1)
    and "source_inspection"."readable" in (0, 1)
    and "source_inspection"."author_known" in (0, 1)
    and "source_inspection"."supports_brand" in (0, 1)
    and ("source_inspection"."support" = 'unknown' or ("source_inspection"."page_live" = 1 and "source_inspection"."readable" = 1 and "source_inspection"."supports_brand" = 1)))
);

CREATE TABLE "stored_object" (
	"id" text PRIMARY KEY NOT NULL,
	"owner_id" text NOT NULL,
	"brand_id" text,
	"class" text NOT NULL,
	"visibility" text NOT NULL,
	"status" text NOT NULL,
	"bucket" text NOT NULL,
	"object_key" text,
	"content_type" text NOT NULL,
	"byte_size" integer NOT NULL,
	"sha256" text NOT NULL,
	"file_name" text,
	"immutable" integer NOT NULL,
	"created_at" text NOT NULL,
	"ready_at" text,
	"deleted_at" text,
	CONSTRAINT "stored_object_check" CHECK ("stored_object"."class" in ('internal-material', 'authorized-media', 'delivery-package', 'report-snapshot', 'owned-export', 'publication-evidence', 'source-original')
    and "stored_object"."visibility" in ('internal', 'public')
    and ("stored_object"."visibility" = 'internal' or "stored_object"."class" = 'authorized-media')
    and "stored_object"."status" in ('pending', 'ready', 'failed', 'tombstoned')
    and "stored_object"."immutable" in (0, 1)
    and (
      ("stored_object"."class" in ('delivery-package', 'report-snapshot', 'owned-export', 'publication-evidence') and "stored_object"."immutable" = 1)
      or ("stored_object"."class" in ('internal-material', 'authorized-media', 'source-original') and "stored_object"."immutable" = 0)
    )
    and (
      ("stored_object"."class" = 'owned-export' and "stored_object"."brand_id" is null and "stored_object"."byte_size" between 1 and 8388608)
      or ("stored_object"."class" <> 'owned-export' and "stored_object"."brand_id" is not null and "stored_object"."byte_size" between 1 and 10485760)
    )
    and length("stored_object"."sha256") = 64
    and "stored_object"."sha256" = lower("stored_object"."sha256")
    and length("stored_object"."bucket") between 3 and 63
    and length("stored_object"."content_type") between 3 and 255
    and length("stored_object"."created_at") between 20 and 40
    and (
      ("stored_object"."class" = 'authorized-media' and "stored_object"."content_type" in ('image/jpeg', 'image/png', 'image/webp'))
      or ("stored_object"."class" = 'publication-evidence' and "stored_object"."content_type" in ('image/jpeg', 'image/png', 'image/webp'))
      or ("stored_object"."class" = 'internal-material' and "stored_object"."content_type" in ('image/jpeg', 'image/png', 'image/webp', 'text/plain', 'text/markdown', 'application/pdf', 'application/json'))
      or ("stored_object"."class" = 'delivery-package' and "stored_object"."content_type" in ('text/markdown', 'text/html', 'application/json'))
      or ("stored_object"."class" = 'report-snapshot' and "stored_object"."content_type" in ('text/html', 'application/json'))
      or ("stored_object"."class" = 'owned-export' and "stored_object"."content_type" = 'application/json')
      or ("stored_object"."class" = 'source-original' and "stored_object"."content_type" in ('text/plain', 'text/markdown', 'application/pdf', 'application/json'))
    )
    and (
      ("stored_object"."status" = 'tombstoned' and "stored_object"."deleted_at" is not null and "stored_object"."file_name" is null and "stored_object"."object_key" is null)
      or ("stored_object"."status" in ('pending', 'failed') and "stored_object"."deleted_at" is null and "stored_object"."ready_at" is null and "stored_object"."file_name" is not null and "stored_object"."object_key" is not null)
      or ("stored_object"."status" = 'ready' and "stored_object"."deleted_at" is null and "stored_object"."ready_at" is not null and "stored_object"."file_name" is not null and "stored_object"."object_key" is not null)
    )
    and (
      "stored_object"."object_key" is null
      or (
        length("stored_object"."object_key") between 8 and 1024
        and "stored_object"."object_key" like 'v1/%'
        and "stored_object"."object_key" not like '%..%'
        and "stored_object"."file_name" is not null
        and length("stored_object"."file_name") between 1 and 120
        and "stored_object"."file_name" not like '%/%'
        and "stored_object"."file_name" not like '%..%'
      )
    )
    and ("stored_object"."ready_at" is null or length("stored_object"."ready_at") between 20 and 40)
    and ("stored_object"."deleted_at" is null or length("stored_object"."deleted_at") between 20 and 40))
);

CREATE TABLE "source_original" (
	"id" text PRIMARY KEY NOT NULL,
	"brand_id" text NOT NULL,
	"owner_id" text NOT NULL,
	"batch_id" text NOT NULL,
	"file_name" text NOT NULL,
	"byte_size" integer NOT NULL,
	"stored_object_id" text,
	"status" text NOT NULL,
	"reason" text,
	"rights_status" text NOT NULL,
	"created_at" text NOT NULL,
	CONSTRAINT "source_original_state_check" CHECK ("source_original"."status" in ('ready', 'partial', 'failed')
    and "source_original"."rights_status" in ('active', 'revoked', 'expired')
    and ("source_original"."reason" is null or "source_original"."reason" in ('encrypted', 'oversized', 'unrecognized', 'batch_limit', 'unavailable'))
    and length("source_original"."file_name") between 1 and 120
    and "source_original"."file_name" not like '%/%'
    and "source_original"."file_name" not like '%..%'
    and length("source_original"."batch_id") between 1 and 64
    and length("source_original"."created_at") between 20 and 40
    and (
      ("source_original"."status" in ('ready', 'partial')
        and "source_original"."stored_object_id" is not null
        and "source_original"."reason" is null
        and "source_original"."byte_size" between 1 and 10485760)
      or ("source_original"."status" = 'failed'
        and "source_original"."stored_object_id" is null
        and "source_original"."reason" is not null
        and "source_original"."rights_status" = 'active'
        and "source_original"."byte_size" between 0 and 2147483647)
    ))
);

CREATE TABLE "sampling_plan" (
	"id" text NOT NULL,
	"version" integer NOT NULL,
	"brand_id" text NOT NULL,
	"owner_id" text NOT NULL,
	"phase" text NOT NULL,
	"currency" text NOT NULL,
	"budget_minor" integer NOT NULL,
	"spent_minor" integer NOT NULL,
	"pending_minor" integer NOT NULL,
	"created_at" text NOT NULL,
	CONSTRAINT "sampling_plan_id_version_pk" PRIMARY KEY("id","version"),
	CONSTRAINT "sampling_plan_state_check" CHECK ("sampling_plan"."version" > 0
    and "sampling_plan"."phase" in ('draft', 'active', 'paused', 'ended')
    and length("sampling_plan"."currency") = 3
    and "sampling_plan"."budget_minor" >= 0 and "sampling_plan"."spent_minor" >= 0 and "sampling_plan"."pending_minor" >= 0
    and length("sampling_plan"."owner_id") between 1 and 128
    and length("sampling_plan"."created_at") between 20 and 40)
);

CREATE TABLE "sampling_slot" (
	"id" text PRIMARY KEY NOT NULL,
	"plan_id" text NOT NULL,
	"brand_id" text NOT NULL,
	"owner_id" text NOT NULL,
	"channel_id" text NOT NULL,
	"at" text NOT NULL,
	"status" text NOT NULL,
	"manual" integer NOT NULL,
	"cost_minor" integer NOT NULL,
	CONSTRAINT "sampling_slot_state_check" CHECK ("sampling_slot"."status" in ('scheduled', 'completed', 'failed', 'paused')
    and "sampling_slot"."manual" in (0, 1)
    and "sampling_slot"."cost_minor" >= 0
    and length("sampling_slot"."channel_id") between 1 and 64
    and length("sampling_slot"."owner_id") between 1 and 128
    and length("sampling_slot"."at") between 20 and 40)
);

CREATE TABLE "quality_alert" (
	"id" text PRIMARY KEY NOT NULL,
	"brand_id" text NOT NULL,
	"owner_id" text NOT NULL,
	"kind" text NOT NULL,
	"window_id" text NOT NULL,
	"status" text NOT NULL,
	"claim_brand_decline" integer NOT NULL,
	"reason" text NOT NULL,
	"created_at" text NOT NULL,
	"updated_at" text NOT NULL,
	CONSTRAINT "quality_alert_state_check" CHECK ("quality_alert"."kind" in ('data_quality', 'trend')
    and "quality_alert"."status" in ('open', 'acknowledged', 'snoozed', 'resolved')
    and "quality_alert"."claim_brand_decline" in (0, 1)
    and (
      ("quality_alert"."kind" = 'data_quality' and "quality_alert"."claim_brand_decline" = 0
        and "quality_alert"."reason" in ('coverage_insufficient', 'citation_field_changed', 'mode_changed'))
      or ("quality_alert"."kind" = 'trend' and "quality_alert"."claim_brand_decline" = 1 and "quality_alert"."reason" = 'recommendation_drop')
    )
    and length("quality_alert"."window_id") between 1 and 64
    and length("quality_alert"."owner_id") between 1 and 128
    and length("quality_alert"."created_at") between 20 and 40
    and length("quality_alert"."updated_at") between 20 and 40)
);

CREATE TABLE "quality_alert_event" (
	"id" text PRIMARY KEY NOT NULL,
	"alert_id" text NOT NULL,
	"brand_id" text NOT NULL,
	"owner_id" text NOT NULL,
	"occurred_at" text NOT NULL,
	CONSTRAINT "quality_alert_event_state_check" CHECK (length("quality_alert_event"."owner_id") between 1 and 128
    and length("quality_alert_event"."occurred_at") between 20 and 40)
);

CREATE TABLE "entity_review" (
	"id" text PRIMARY KEY NOT NULL,
	"brand_id" text NOT NULL,
	"owner_id" text NOT NULL,
	"observation_id" text NOT NULL,
	"analysis_version_id" text NOT NULL,
	"confirmed_error" integer NOT NULL,
	"reviewed" integer NOT NULL,
	"population_count" integer NOT NULL,
	"method" text NOT NULL,
	"fact" text NOT NULL,
	"created_at" text NOT NULL,
	CONSTRAINT "entity_review_state_check" CHECK ("entity_review"."confirmed_error" in (0, 1)
    and "entity_review"."reviewed" in (0, 1)
    and "entity_review"."fact" in ('active', 'expired', 'conflict')
    and ("entity_review"."confirmed_error" = 0 or ("entity_review"."reviewed" = 1 and "entity_review"."fact" = 'active'))
    and "entity_review"."population_count" between 1 and 100000
    and length("entity_review"."method") between 1 and 200
    and length("entity_review"."owner_id") between 1 and 128
    and length("entity_review"."observation_id") = 36
    and length("entity_review"."analysis_version_id") = 36
    and length("entity_review"."created_at") between 20 and 40)
);

CREATE TABLE "entity_correction" (
	"id" text PRIMARY KEY NOT NULL,
	"brand_id" text NOT NULL,
	"owner_id" text NOT NULL,
	"observation_id" text NOT NULL,
	"action" text NOT NULL,
	"effect" text NOT NULL,
	"created_at" text NOT NULL,
	CONSTRAINT "entity_correction_state_check" CHECK ((("entity_correction"."action" = 'open' and "entity_correction"."effect" in ('open', 'unresolved'))
      or ("entity_correction"."action" = 'actioned' and "entity_correction"."effect" in ('pending_retest', 'unresolved')))
    and length("entity_correction"."owner_id") between 1 and 128
    and length("entity_correction"."observation_id") = 36
    and length("entity_correction"."created_at") between 20 and 40)
);

CREATE TABLE "entity_disambiguation" (
	"id" text PRIMARY KEY NOT NULL,
	"brand_id" text NOT NULL,
	"owner_id" text NOT NULL,
	"observation_id" text NOT NULL,
	"prior_analysis_id" text NOT NULL,
	"next_analysis_id" text NOT NULL,
	"count_as_target_mention" integer NOT NULL,
	"created_at" text NOT NULL,
	CONSTRAINT "entity_disambiguation_state_check" CHECK ("entity_disambiguation"."count_as_target_mention" = 0
    and "entity_disambiguation"."prior_analysis_id" <> "entity_disambiguation"."next_analysis_id"
    and length("entity_disambiguation"."owner_id") between 1 and 128
    and length("entity_disambiguation"."observation_id") = 36
    and length("entity_disambiguation"."prior_analysis_id") = 36
    and length("entity_disambiguation"."next_analysis_id") = 36
    and length("entity_disambiguation"."created_at") between 20 and 40)
);

